#!/usr/bin/env bash
# Precompress static assets for Caddy's `file_server { precompressed br gzip }`.
# Generated by devstack. Re-run after editing files in static/ or error/: Caddy
# serves a .br/.gz copy whenever one exists, so a stale copy hides your edit.
#   usage: infra/compress-static.sh static error
set -euo pipefail

if [ "$#" -eq 0 ]; then
  echo "usage: $0 DIR..." >&2
  exit 2
fi

find "$@" -type f \
  ! -name '*.br' ! -name '*.gz' ! -name '*.ts' \
  ! -name '*.avif' ! -name '*.webp' ! -name '*.png' ! -name '*.jpg' ! -name '*.jpeg' \
  ! -name '*.woff2' ! -name '*.mp4' ! -name '*.webm' \
  -print0 |
  while IFS= read -r -d '' f; do
    [ "$f.br" -nt "$f" ] || brotli --best --force --output="$f.br" "$f"
    [ "$f.gz" -nt "$f" ] || gzip --best --keep --force "$f"
  done
